def transform(grid):
    """Transform: extend anti-diagonals with >=2 non-bg cells."""
    bg_val = grid[0][0]
    non_bg = defaultdict(list)
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            val = grid[i][j]
            if val != bg_val:
                non_bg[i + j].append((i, j, val))

    out = [[bg_val for _ in range(len(grid[0]))] for _ in range(len(grid))]

    for ad, cells in non_bg.items():
        if len(cells) >= 2:
            sorted_cells = sorted(cells, key=lambda x: x[0])
            first_val = sorted_cells[0][2]
            last_val = sorted_cells[-1][2]
            first_row = sorted_cells[0][0]
            last_row = sorted_cells[-1][0]

            # Fill above pattern with first_val
            for r in range(0, first_row):
                c = ad - r
                if 0 <= c < len(grid[0]):
                    out[r][c] = first_val

            # Fill below pattern with last_val
            for r in range(last_row + 1, len(grid)):
                c = ad - r
                if 0 <= c < len(grid[0]):
                    out[r][c] = last_val

            # Keep original pattern values
            for r, c, val in cells:
                out[r][c] = val

    return out

