import os, re, json
from collections import defaultdict

d = os.environ['RLM_SESSION_DIR']
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo_in = G['Demo pair 1 input']
demo_out = G['Demo pair 1 output']
h, w = 19, 11
bg_val = 4

pattern_cells = set((r, c) for r in range(h) for c in range(w) if demo_in[r][c] != bg_val)

def transform(grid):
    """Transform grid according to hypothesis"""
    result = [[grid[r][c] if grid[r][c] != bg_val and (r,c) in pattern_cells else bg_val 
               for c in range(w)] for r in range(h)]

    bg_val = grid[0][0]
    pattern_cells = set((r, c) for r in range(h) for c in range(w) if grid[r][c] != bg_val)

    # Process anti-diags
    ad_groups = defaultdict(list)
    for r, c in pattern_cells:
        ad_groups[r + c].append((r, c, grid[r][c]))

    for ad in ad_groups:
        if len(ad_groups[ad]) < 2:
            continue

        # Group by value
        val_groups = defaultdict(list)
        for cell in ad_groups[ad]:
            val_groups[cell[2]].append(cell)

        for val, group in val_groups.items():
            if len(group) < 2:
                continue

            # Sort by row (ascending)
            group = sorted(group, key=lambda x: x[0])

            # Extend from topmost backward (up-right = dr=-1, dc=1)
            top = group[0]
            r, c = top[0], top[1]
            while True:
                nr, nc = r - 1, c + 1
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

            # Extend from bottommost forward (down-left = dr=1, dc=-1)
            bottom = group[-1]
            r, c = bottom[0], bottom[1]
            while True:
                nr, nc = r + 1, c - 1
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

    # Process row-cols
    acr_groups = defaultdict(list)
    for r, c in pattern_cells:
        acr_groups[r - c].append((r, c, grid[r][c]))

    for acr in acr_groups:
        if len(acr_groups[acr]) < 2:
            continue

        val_groups = defaultdict(list)
        for cell in acr_groups[acr]:
            val_groups[cell[2]].append(cell)

        for val, group in val_groups.items():
            if len(group) < 2:
                continue

            group = sorted(group, key=lambda x: x[0])

            # Extend left/up from topmost (dr=-1, dc=-1)
            top = group[0]
            r, c = top[0], top[1]
            while True:
                nr, nc = r - 1, c - 1
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

            # Extend right/down from bottommost (dr=1, dc=1)
            bottom = group[-1]
            r, c = bottom[0], bottom[1]
            while True:
                nr, nc = r + 1, c + 1
                if 0 <= nr < h and 0 <= nc < w:
                    result[nr][nc] = val
                    r, c = nr, nc
                else:
                    break

    return result

print("Testing transformation:")
result = transform(demo_in)

# Compare
matches = 0
mismatch = []
for r in range(h):
